def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    prev_bids = []
    dangerous_pressure = 0.0
    rich_alive = 0
    desperate_alive = 0
    for opp in alive:
        obudget = opp.get('budget', 0)
        ohp = opp.get('hp', 0)
        ono = opp.get('no_water_days', 0)
        if obudget >= 140:
            rich_alive += 1
        if ohp <= 3 or ono >= 2:
            desperate_alive += 1
        prev = opp.get('previous_trace', {})
        if prev:
            pbid = prev.get('bid')
            if pbid is not None:
                prev_bids.append(float(pbid))
                if obudget > 0 and opp.get('alive'):
                    dangerous_pressure = max(dangerous_pressure, float(pbid))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = supply / WATER_REQ
    scarce = units < 1.6
    medium = units < 1.9

    urgency = 0
    if hp <= 2 or no_water_days >= 2:
        urgency = 3
    elif hp <= 4 or no_water_days >= 1:
        urgency = 2
    elif hp <= 6:
        urgency = 1

    if urgency == 3:
        base = 92.0
        if scarce:
            base = 108.0
        elif medium:
            base = 98.0
        bid = max(base, max_prev + 3.0)
    elif urgency == 2:
        base = 58.0
        if scarce:
            base = 76.0
        elif medium:
            base = 66.0
        bid = max(base, dangerous_pressure + 2.0)
    elif urgency == 1:
        base = 34.0
        if scarce:
            base = 48.0
        elif medium:
            base = 40.0
        bid = max(base, min(dangerous_pressure + 1.0, 72.0))
    else:
        if scarce:
            bid = max(28.0, min(avg_prev + 1.0, 55.0))
        elif medium:
            bid = 24.0
        else:
            bid = 18.0

    if rich_alive >= 1 and urgency <= 1:
        bid *= 0.92
    if desperate_alive >= 2 and urgency == 0:
        bid *= 0.9

    if day >= 8:
        bid += 6.0
    elif day >= 5 and urgency >= 1:
        bid += 4.0

    reserve_floor = 0.0
    if hp > 4 and day <= 6:
        reserve_floor = 70.0
    max_affordable = max(0.0, budget - reserve_floor)
    if urgency >= 2:
        max_affordable = budget

    bid = min(bid, max_affordable)
    if urgency >= 2 and bid < 20.0 and budget >= 20.0:
        bid = min(budget, 20.0)

    if bid < 0:
        bid = 0.0
    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    current_bid = 0.0

    if my_status['hp'] <= 2:
        current_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        current_bid = DAILY_SALARY * 0.8
    else:
        current_bid = DAILY_SALARY * 0.6

        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            if highest_prev_bid >= DAILY_SALARY * 0.7:
                current_bid = max(current_bid, highest_prev_bid + 1.0)
            else:
                current_bid = max(current_bid, highest_prev_bid + 0.5)
        else:
            # If no previous bids, use a sensible default if not already set high by HP
            current_bid = max(current_bid, DAILY_SALARY * 0.5)

        total_players = num_alive_opponents + 1
        water_needed_total = total_players * WATER_REQ

        if day_context['supply'] < water_needed_total:
            if current_bid < DAILY_SALARY * 0.85:
                current_bid = min(DAILY_SALARY * 0.85, current_bid * 1.1)
        else:
            if my_status['hp'] > 5 and current_bid > DAILY_SALARY * 0.5:
                current_bid = max(DAILY_SALARY * 0.5, current_bid * 0.9)

    final_bid = min(my_status['budget'], current_bid)
    return max(0.0, final_bid)

